import os
from flask import Flask, request, jsonify, abort

app = Flask(__name__)

# Directory where images are stored (adjust as needed)
IMAGE_ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), "images"))
ALLOWED_EXTENSIONS = {".png", ".jpg", ".jpeg", ".gif", ".bmp", ".webp"}

def _is_safe_path(base_path: str, target_path: str) -> bool:
    """Return True if target_path is inside base_path."""
    return os.path.commonpath([base_path, target_path]) == base_path

@app.route('/deleteImage', methods=['POST'])
def deleteImage():
    """
    Get file name from request, validate the request, and delete the image file.
    Expected JSON payload: {"filename": "example.png"}
    Returns JSON with status and optional message.
    """
    data = request.get_json(silent=True) or {}
    filename = data.get("filename", "").strip()

    if not filename:
        abort(400, description="Missing 'filename' parameter.")

    # Disallow path traversal characters
    if os.path.sep in filename or os.path.altsep and os.path.altsep in filename:
        abort(400, description="Invalid filename.")

    # Validate extension
    _, ext = os.path.splitext(filename)
    if ext.lower() not in ALLOWED_EXTENSIONS:
        abort(400, description="Unsupported file type.")

    # Build absolute path and ensure it stays within IMAGE_ROOT
    target_path = os.path.abspath(os.path.join(IMAGE_ROOT, filename))
    if not _is_safe_path(IMAGE_ROOT, target_path):
        abort(400, description="Invalid file path.")

    # Attempt to delete the file
    try:
        if not os.path.isfile(target_path):
            abort(404, description="File not found.")
        os.remove(target_path)
    except PermissionError:
        abort(403, description="Insufficient permissions to delete the file.")
    except OSError as e:
        abort(500, description=f"Error deleting file: {e}")

    return jsonify({"status": "success", "message": f"'{filename}' deleted."}), 200
